const { brief, llmConfig } = $json;
const SERP_KEY = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

function encParam(s) {
  return encodeURIComponent(String(s || ''));
}

async function serpSearch(engine, query, extraParams) {
  let url = 'https://serpapi.com/search?api_key=' + SERP_KEY 
    + '&engine=' + encParam(engine) 
    + '&q=' + encParam(query)
    + '&num=10';
  if (extraParams) {
    for (const [k, v] of Object.entries(extraParams)) {
      url += '&' + encParam(k) + '=' + encParam(v);
    }
  }
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: url,
      json: true
    });
    return resp;
  } catch(e) {
    return { error: e.message };
  }
}

async function fetchUrl(url) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: url
    });
    return typeof resp === 'string' ? resp.substring(0, 5000) : JSON.stringify(resp).substring(0, 5000);
  } catch(e) {
    return 'Failed to fetch: ' + e.message;
  }
}

const results = {};

// 1. Google search for brand + product
results.brand_search = await serpSearch.call(this, 'google',
  brief.brand_name + ' ' + brief.product_feature + ' review');

// 2. Amazon review search
