// Format results
function extractResults(data) {
  if (!data || data.error) return 'Search failed: ' + (data ? data.error : 'unknown');
  if (data.organic_results) return data.organic_results.slice(0, 8).map(function(r) {
    return '- ' + r.title + '\n  ' + r.link + '\n  ' + (r.snippet || '');
  }).join('\n');
  if (data.video_results) return data.video_results.slice(0, 8).map(function(r) {
    return '- ' + r.title + ' (' + (r.length || 'N/A') + ')\n  ' + r.link + '\n  Channel: ' + (r.channel ? r.channel.name : 'N/A') + ' | Views: ' + (r.views || 'N/A');
  }).join('\n');
  if (data.inline_videos) return data.inline_videos.slice(0, 5).map(function(r) {
    return '- ' + r.title + '\n  ' + r.link;
  }).join('\n');
  return JSON.stringify(data).substring(0, 2000);
}

const researchData = '=== BRAND & PRODUCT SEARCH ===\n' + extractResults(results.brand_search)
