// AI-tell phrases to penalize
const aiTells = [
  'game-changer', 'game changer', 'revolutionize', 'revolutionized', 'elevate', 'elevates', 'elevated',
  'unlock', 'unlocking', 'seamlessly', 'seamless', 'cutting-edge', 'cutting edge',
