const authenticityMarkers = [
  '[beat]', '[pause]', '[laughs]', '[looks', '[sighs]', '[processing]',
  'wait,', 'actually', 'honestly', 'like,', 'um,', 'okay let me',
  'anyway,', 'point is', 'I sound crazy', 'no but seriously',
  '\u2014', '...', 'I\u2014', 'so\u2014', 'but\u2014'
];

function scoreVersion(text) {
  if (!text) return { score: 0, aiTellCount: 99, avgSentenceLen: 999, authenticMarkers: 0 };
  const lower = text.toLowerCase();

  // Count AI tells (bad)
  let aiTellCount = 0;
  for (const tell of aiTells) {
    const regex = new RegExp(tell.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&'), 'gi');
    const matches = lower.match(regex);
    if (matches) aiTellCount += matches.length;
  }

  // Count authenticity markers (good)
  let authenticMarkerCount = 0;
  for (const marker of authenticityMarkers) {
    if (text.includes(marker) || lower.includes(marker.toLowerCase())) {
      authenticMarkerCount++;
    }
  }

  // Average sentence length (shorter = more authentic for UGC)
  const sentences = text.split(/[.!?]+/).filter(s => s.trim().length > 3);
  const avgLen = sentences.length > 0 ? sentences.reduce((sum, s) => sum + s.trim().split(/\s+/).length, 0) / sentences.length : 20;

  // Score: higher is better
  // Penalize AI tells heavily (-5 each), reward authenticity markers (+2 each)
  // Penalize long average sentence length
  const score = 100 - (aiTellCount * 5) + (authenticMarkerCount * 2) - (Math.max(0, avgLen - 10) * 1.5);

  return { score, aiTellCount, avgSentenceLen: Math.round(avgLen * 10) / 10, authenticMarkers: authenticMarkerCount };
}

