function flattenScript(obj) {
  const flat = {};

  // Copy simple string/number fields
  for (const [k, v] of Object.entries(obj)) {
    if (typeof v === 'string' || typeof v === 'number') {
      flat[k] = v;
    }
  }

  // Handle nested script object (e.g., creative_concept.script)
  if (obj.script && typeof obj.script === 'object') {
    for (const [k, v] of Object.entries(obj.script)) {
      if (typeof v === 'string' || typeof v === 'number') {
        flat[k] = v;
      }
    }

    // Flatten video_sections into full_script
    if (obj.script.video_sections && Array.isArray(obj.script.video_sections)) {
      const sections = obj.script.video_sections;
      const scriptParts = [];
      const visualParts = [];
      const textOverlays = [];

      for (const section of sections) {
        if (section.section_name) scriptParts.push('[' + section.section_name + ']');
        if (section.visuals) visualParts.push((section.section_name || '') + ': ' + section.visuals);

        // Extract dialogue
        const dialogues = section.creator_dialogue || section.dialogue || [];
        if (Array.isArray(dialogues)) {
          for (const d of dialogues) {
            if (typeof d === 'string') {
              scriptParts.push(d);
            } else if (d.dialogue) {
              const notes = d.notes ? ' [' + d.notes + ']' : '';
              scriptParts.push(d.dialogue + notes);
            }
          }
        } else if (typeof dialogues === 'string') {
          scriptParts.push(dialogues);
        }

        // Extract on-screen text
        if (section.on_screen_text) {
          if (Array.isArray(section.on_screen_text)) {
            textOverlays.push(...section.on_screen_text);
          } else {
            textOverlays.push(section.on_screen_text);
          }
        }
      }

      if (!flat.full_script && scriptParts.length > 0) {
        flat.full_script = scriptParts.join('\n\n');
      }
      if (!flat.visual_direction && visualParts.length > 0) {
        flat.visual_direction = visualParts.join('\n');
      }
      if (textOverlays.length > 0 && !flat.on_screen_text) {
        flat.on_screen_text = textOverlays;
      }
    }
  }

  return flat;
}

