// Build learning extraction prompt from QA verdict data
const verdictData = $input.first().json;
const brief = $('Select LLM Config').first().json.brief;
const llmConfig = $('Select LLM Config').first().json.llmConfig;

// Get existing learnings from the Fetch Brand/Agency Learnings nodes (for dedup in next step)
let existingLearnings = [];
try {
  const brandFetched = $('Fetch Brand Learnings').first().json;
  const agencyFetched = $('Fetch Agency Learnings').first().json;
  const allRecords = [...(brandFetched?.records || []), ...(agencyFetched?.records || [])];
  if (allRecords.length > 0) {
    existingLearnings = allRecords.map(r => ({
      title: (r.fields || {}).title || '',
      category: (r.fields || {}).category || '',
      insight: (r.fields || {}).insight || ''
    }));
  }
} catch(e) {
  // Fetch may not have returned data — that's fine
}

const systemPrompt = `You are a UGC advertising learning analyst. You analyze QA review sessions and extract actionable learnings that can improve future script writing. You are precise and only extract genuine insights — never fabricate patterns from insufficient data.`;

const userPrompt = `Analyze this QA review session and extract 1-3 meaningful learnings. Only extract learnings if there are clear patterns — do NOT force insights where none exist.

== CONTEXT ==
Brand: ${brief.brand_name || 'Unknown'}
Industry: ${brief.industry || 'Unknown'}
Product: ${brief.product_feature || 'Unknown'}
Target Audience: ${brief.target_user || 'Unknown'}

== QA VERDICT ==
Overall Verdict: ${verdictData.verdict}
Overall Quality Score: ${verdictData.overall_quality || 'N/A'}
Revision Count: ${verdictData.revision_count || 0}
Batch Notes: ${verdictData.revision_notes || 'None'}

== SCRIPT REVIEWS ==
${JSON.stringify(verdictData.script_reviews || [], null, 2)}

== INSTRUCTIONS ==
Extract learnings about what worked or didn't in this batch. Good learnings look like:
- "Scripts with hooks under 5 words scored 8+ on authenticity"
- "Question-format hooks got lowest engagement_potential scores"
- "Brand voice alignment drops when scripts exceed 45 seconds"
- "Skincare scripts using specific ingredient names scored higher"
- "Scripts that passed QA on first attempt used [X pattern]"

Categories: script_quality, hook_patterns, audience_insight, ad_performance

Output ONLY valid JSON:
{
  "learnings": [
    {
      "title": "Short descriptive title (max 80 chars)",
      "category": "one of the 4 categories above",
      "insight": "Detailed insight with evidence from this QA session (2-3 sentences)",
      "confidence": 0.7
    }
  ]
}

If there are no meaningful patterns to extract, return: { "learnings": [] }
Output ONLY valid JSON.`;

const requestBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 2048 }
};

// Pass through ALL verdict data so downstream nodes (Revision Needed?) still get it
return [{
  json: {
    ...verdictData,
    _learning_request: requestBody,
    _learning_url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
    _existing_learnings: existingLearnings,
    _brand_name: brief.brand_name || 'Unknown'
  }
}];

// Parse Gemini response and dedup against existing learnings
const input = $input.first().json;

// Pass through all verdict data
const passThrough = {};
for (const [k, v] of Object.entries(input)) {
  if (!k.startsWith('_learning_') && !k.startsWith('_existing_') && !k.startsWith('_brand_') && k !== 'candidates' && k !== 'usageMetadata' && k !== 'modelVersion') {
    passThrough[k] = v;
  }
}

// Extract verdict data that was passed through the HTTP Request node
// HTTP Request replaces $json with response, but we need verdict data
// Re-read from the build-learning-prompt node
const verdictKeys = ['verdict', 'needs_revision', 'revision_count', 'revision_notes', 'script_reviews', 'overall_quality', 'writer_output', 'qa_output'];
const buildNode = $('sa-build-learning-prompt').first().json;
const verdictData = {};
for (const k of verdictKeys) {
  if (buildNode[k] !== undefined) verdictData[k] = buildNode[k];
}

let learningsCount = 0;
let batch = { records: [] };

try {
  // Extract Gemini response text
  const candidates = input.candidates || [];
  const rawText = (candidates[0] && candidates[0].content && candidates[0].content.parts && candidates[0].content.parts[0] && candidates[0].content.parts[0].text) || '';

  // Strip code fences
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(cleaned);
  } catch(e) {
    const match = cleaned.match(/\{[\s\S]*\}/);
    if (match) {
      parsed = JSON.parse(match[0]);
    } else {
      parsed = { learnings: [] };
    }
  }

  const newLearnings = parsed.learnings || [];
  const existing = buildNode._existing_learnings || [];

  // Dedup: compare titles with >50% word overlap
  function wordOverlap(a, b) {
    const wordsA = a.toLowerCase().split(/\s+/).filter(w => w.length > 2);
    const wordsB = b.toLowerCase().split(/\s+/).filter(w => w.length > 2);
    if (wordsA.length === 0 || wordsB.length === 0) return 0;
    const setB = new Set(wordsB);
    const overlap = wordsA.filter(w => setB.has(w)).length;
    return overlap / Math.max(wordsA.length, wordsB.length);
  }

  const uniqueLearnings = newLearnings.filter(nl => {
    return !existing.some(ex => wordOverlap(ex.title, nl.title) > 0.5 || wordOverlap(ex.insight, nl.insight) > 0.5);
  });

  const brandName = buildNode._brand_name || 'Unknown';
  const verdict = verdictData.verdict || 'UNKNOWN';
  const quality = verdictData.overall_quality || 'N/A';

  batch.records = uniqueLearnings.map(l => ({
    fields: {
      title: l.title,
      source_agent: 'script_agent',
      category: l.category,
      insight: l.insight,
      evidence: 'QA session for ' + brandName + ' — verdict: ' + verdict + ', quality: ' + quality,
      confidence: l.confidence || 0.5,
      active: true,
      created_at: new Date().toISOString()
    }
  }));

  learningsCount = batch.records.length;
} catch(e) {
  // If anything fails, just skip — don't break the pipeline
  learningsCount = 0;
}

return [{
  json: {
    ...verdictData,
    learningsCount,
    batch
  }
}];

// Pass through QA verdict data after learning write
// The HTTP Request node replaced $json with Airtable response
// Restore verdict data from the dedup node
const verdictData = $('sa-dedup-learnings').first().json;
return [{
  json: {
    verdict: verdictData.verdict,
    needs_revision: verdictData.needs_revision,
    revision_count: verdictData.revision_count,
    revision_notes: verdictData.revision_notes,
    script_reviews: verdictData.script_reviews,
    overall_quality: verdictData.overall_quality,
    writer_output: verdictData.writer_output,
    qa_output: verdictData.qa_output
  }
}];

